/*!
 * bignumber.min.js — minimal big-number arithmetic wrapper for RuneSimulator
 * ---------------------------------------------------------------------------
 * NOTE FOR DEVELOPERS:
 * This project runs fully offline (no CDN / npm access), so instead of
 * fetching a third-party arbitrary-precision library, this file provides a
 * small BigNumber class backed by native JS doubles.
 *
 * Why this is safe here: the largest values in the rune database top out
 * around 1e66 (e.g. "2.5UVt"). Even after multiplying by bulk (up to ~1e20),
 * luck, and long time spans, realistic totals stay far under 1e308 — the
 * point where JS doubles overflow to Infinity. Doubles give ~15-17
 * significant digits of precision, which is more than enough since the UI
 * only ever displays 2-4 significant figures.
 *
 * If a future content update pushes numbers past ~1e300, swap the internals
 * of this class for a true arbitrary-precision (mantissa/exponent) engine —
 * the public API below (plus/minus/times/div/pow/compare/toString) is
 * designed to stay stable so nothing else in the codebase would need to change.
 */
(function (root) {
    "use strict";

    function toNum(v) {
        if (v instanceof BigNumber) return v._n;
        if (typeof v === "number") return v;
        if (typeof v === "string") return BigNumber.prototype._parsePlain(v);
        return Number(v);
    }

    function BigNumber(value) {
        if (!(this instanceof BigNumber)) return new BigNumber(value);
        if (value instanceof BigNumber) {
            this._n = value._n;
        } else if (typeof value === "number") {
            this._n = value;
        } else if (typeof value === "string") {
            this._n = this._parsePlain(value);
        } else {
            this._n = Number(value) || 0;
        }
    }

    BigNumber.prototype._parsePlain = function (str) {
        var s = String(str).trim().replace(/,/g, "");
        var n = Number(s);
        return isNaN(n) ? 0 : n;
    };

    BigNumber.prototype.plus = function (o) { return new BigNumber(this._n + toNum(o)); };
    BigNumber.prototype.minus = function (o) { return new BigNumber(this._n - toNum(o)); };
    BigNumber.prototype.times = function (o) { return new BigNumber(this._n * toNum(o)); };
    BigNumber.prototype.div = function (o) {
        var d = toNum(o);
        return new BigNumber(d === 0 ? 0 : this._n / d);
    };
    BigNumber.prototype.pow = function (n) { return new BigNumber(Math.pow(this._n, toNum(n))); };
    BigNumber.prototype.abs = function () { return new BigNumber(Math.abs(this._n)); };
    BigNumber.prototype.floor = function () { return new BigNumber(Math.floor(this._n)); };
    BigNumber.prototype.ceil = function () { return new BigNumber(Math.ceil(this._n)); };
    BigNumber.prototype.round = function () { return new BigNumber(Math.round(this._n)); };
    BigNumber.prototype.min = function (o) { return new BigNumber(Math.min(this._n, toNum(o))); };
    BigNumber.prototype.max = function (o) { return new BigNumber(Math.max(this._n, toNum(o))); };

    BigNumber.prototype.eq = function (o) { return this._n === toNum(o); };
    BigNumber.prototype.lt = function (o) { return this._n < toNum(o); };
    BigNumber.prototype.lte = function (o) { return this._n <= toNum(o); };
    BigNumber.prototype.gt = function (o) { return this._n > toNum(o); };
    BigNumber.prototype.gte = function (o) { return this._n >= toNum(o); };
    BigNumber.prototype.cmp = function (o) {
        var a = this._n, b = toNum(o);
        return a === b ? 0 : (a < b ? -1 : 1);
    };
    BigNumber.prototype.isZero = function () { return this._n === 0; };
    BigNumber.prototype.isFinite = function () { return isFinite(this._n); };
    BigNumber.prototype.isNaN = function () { return isNaN(this._n); };

    BigNumber.prototype.toNumber = function () { return this._n; };
    BigNumber.prototype.valueOf = function () { return this._n; };
    BigNumber.prototype.toExponential = function (d) { return this._n.toExponential(d); };

    BigNumber.max = function (a, b) { return new BigNumber(Math.max(toNum(a), toNum(b))); };
    BigNumber.min = function (a, b) { return new BigNumber(Math.min(toNum(a), toNum(b))); };
    BigNumber.from = function (v) { return new BigNumber(v); };

    root.BigNumber = BigNumber;
})(typeof window !== "undefined" ? window : this);
